func newTestDB(t *testing.T) *WebsiteStateDB {
	t.Helper()
	path := filepath.Join(t.TempDir(), "cache.db")
	db, err := NewWebsiteStateDB(path)
	if err != nil {
		t.Fatalf("open WebsiteStateDB: %v", err)
	}
	t.Cleanup(func() { db.Close() })
	return db
}

// rawInsert ports the healing tests' _raw_insert: historical rows the
// buggy era wrote, straight through the connection.
func rawInsert(t *testing.T, db *WebsiteStateDB, table string,
	cols []string, vals ...any) {
	t.Helper()
	db.Lock()
	defer db.Unlock()
	ph := make([]string, len(cols))
	for i := range ph {
		ph[i] = "?"
	}
	if _, err := db.SQL().Exec(
		"INSERT OR REPLACE INTO "+table+" ("+strings.Join(cols, ", ")+
			") VALUES ("+strings.Join(ph, ",")+")", vals...); err != nil {
		t.Fatalf("raw insert into %s: %v", table, err)
	}
}

