// The settled half of TestTheStateBoundary, adapted: settle_urls is dead
// code in the reference (no production callers; module spec "Dead:
// settle_urls") and is not ported — SettleExisting's extras fold runs
// the SAME normalize + order-preserving dedupe path, so the one-spelling
// verdict is pinned through it.
func TestStateBoundarySettledOneSpelling(t *testing.T) {
	db := newTestDB(t)
	rep, err := db.SettleExisting([]string{withSlash, noSlash, "", ""})
	if err != nil {
		t.Fatal(err)
	}
	if rep.Settled != 1 {
		t.Fatalf("settled = %d; want 1 (one spelling, one row)", rep.Settled)
	}
	if n, err := db.SettledCount(); err != nil || n != 1 {
		t.Fatalf("settled_count = %d, err = %v", n, err)
	}
	for _, u := range []string{noSlash, withSlash} {
		if ok, err := db.IsSettled(u); err != nil || !ok {
			t.Fatalf("is_settled(%s) = %v, err = %v", u, ok, err)
		}
	}
	if ok, err := db.Unsettle(withSlash); err != nil || !ok {
		t.Fatalf("unsettle = %v, err = %v", ok, err)
	}
	if ok, err := db.IsSettled(noSlash); err != nil || ok {
		t.Fatalf("is_settled after unsettle = %v, err = %v", ok, err)
	}
}

