// The unsettle half of test_settle_urls_and_unsettle_round_trip (the
// settle_urls half is dead code — see the package doc).
func TestUnsettleHonestBooleans(t *testing.T) {
	db := newTestDB(t)
	if _, err := db.SettleExisting([]string{
		"https://x.example/", "https://x.example/"}); err != nil {
		t.Fatal(err)
	}
	if ok, err := db.IsSettled("https://x.example/"); err != nil || !ok {
		t.Fatalf("is_settled = %v, err = %v", ok, err)
	}
	if n, err := db.SettledCount(); err != nil || n != 1 {
		t.Fatalf("settled_count = %d, err = %v", n, err)
	}
	// the ♻️ door back
	if ok, err := db.Unsettle("https://x.example/"); err != nil || !ok {
		t.Fatalf("unsettle = %v, err = %v", ok, err)
	}
	if ok, err := db.IsSettled("https://x.example/"); err != nil || ok {
		t.Fatalf("is_settled after unsettle = %v, err = %v", ok, err)
	}
	// honest False for a URL that was never settled
	if ok, err := db.Unsettle("https://y.example/"); err != nil || ok {
		t.Fatalf("unsettle(never settled) = %v, err = %v", ok, err)
	}
}

