// test_masterretry.py: TestResetRetryAttempts — the surgical reborn.
// ---------------------------------------------------------------------------

func TestResetRetryAttemptsOneBurnedOutRowIsReborn(t *testing.T) {
	db := newTestDB(t)
	for i := 0; i < 3; i++ {
		if err := db.EnqueueRetry("https://m.example.org/p",
			"boom"); err != nil {
			t.Fatal(err)
		}
	}
	row, err := db.RetryRow("https://m.example.org/p")
	if err != nil || row == nil || row.Attempts != 3 {
		t.Fatalf("burned row = %+v, err = %v", row, err)
	}
	other := "https://other.example.org/p"
	if err := db.EnqueueRetry(other, "boom"); err != nil {
		t.Fatal(err)
	}
	if ok, err := db.ResetRetryAttempts("https://m.example.org/p"); err != nil || !ok {
		t.Fatalf("reset = %v, err = %v", ok, err)
	}
	row, err = db.RetryRow("https://m.example.org/p")
	if err != nil || row == nil {
		t.Fatalf("row after reset = %v, err = %v", row, err)
	}
	if row.Attempts != 0 {
		t.Fatalf("attempts after reset = %d; want 0", row.Attempts)
	}
	if row.NextAttemptAt == nil {
		t.Fatal("next_attempt_at is NULL after reset")
	}
	// surgical: the OTHER row keeps its attempt count
	orow, err := db.RetryRow(other)
	if err != nil || orow == nil || orow.Attempts != 1 {
		t.Fatalf("other row = %+v, err = %v (want attempts 1)", orow, err)
	}
}

