// ---------------------------------------------------------------------------
// The generated pure corpus — TestPureGolden.
// ---------------------------------------------------------------------------

type pureGolden struct {
	Schema    int `json:"schema"`
	Constants struct {
		MaxFetchRetries          int64  `json:"MAX_FETCH_RETRIES"`
		RetryBackoffDays         int64  `json:"RETRY_BACKOFF_DAYS"`
		SettledMetaKey           string `json:"SETTLED_META_KEY"`
		QueueHistorySettledMetaK string `json:"QUEUE_HISTORY_SETTLED_META_KEY"`
	} `json:"constants"`
	KeyCases       [][]string     `json:"key_cases"`
	Backoff        []backoffEntry `json:"backoff"`
	BackoffRefresh map[string]any `json:"backoff_refresh"`
	Truncation     map[string]any `json:"truncation"`
}

type backoffEntry struct {
	Attempt                    int64   `json:"attempt"`
	DeltaDays                  float64 `json:"delta_days"`
	ErrorField                 string  `json:"error_field"`
	FirstEqualsLastOnFirstFail bool    `json:"first_equals_last_on_first_failure"`
}

func TestPureGolden(t *testing.T) {
	var g pureGolden
	decodeGolden(t, "websitestate_pure.golden.json", &g)

	// The constants.
	if MaxFetchRetries != int(g.Constants.MaxFetchRetries) ||
		RetryBackoffDays != int(g.Constants.RetryBackoffDays) ||
		SettledMetaKey != g.Constants.SettledMetaKey ||
		QueueHistorySettledMetaKey != g.Constants.QueueHistorySettledMetaK {
		t.Fatalf("constants drifted: %+v", g.Constants)
	}

	// The _key boundary battery — the Python list order, with the None
	// and '' cases both mapped to Go's "".
	inputs := []string{
		withSlash, noSlash,
		"https://example.com/deep/path/", "https://example.com/deep/path",
		"https://example.com/p?a=1&utm_source=x", "https://example.com/p",
		"HTTPS://EXAMPLE.COM/Page", "  https://example.com/whitespace  ",
		"https://example.com/trailing?", "", "",
		"not a url at all", "::::", "https://",
	}
	if len(inputs) != len(g.KeyCases) {
		t.Fatalf("key battery length = %d; golden has %d",
			len(inputs), len(g.KeyCases))
	}
	for i, in := range inputs {
		if got := StateKey(in); got != g.KeyCases[i][1] {
			t.Errorf("StateKey(%q) = %q; golden[%d] = %q",
				in, got, i, g.KeyCases[i][1])
		}
	}

	// The backoff table: fresh rows, the (next - last) delta in days.
	bdb := newTestDB(t)
	for i := 0; i < len(g.Backoff); i++ {
		url := fmt.Sprintf("https://backoff%d.example/", i)
		if err := bdb.EnqueueRetry(url, "e"); err != nil {
			t.Fatal(err)
		}
		row, err := bdb.RetryRow(url)
		if err != nil || row == nil {
			t.Fatalf("retry_row = %v, err = %v", row, err)
		}
		nxt := mustParsePyISO(t, pstr(row.NextAttemptAt))
		last := mustParsePyISO(t, pstr(row.LastFailedAt))
		delta := nxt.Sub(last).Hours() / 24
		if row.Attempts != g.Backoff[i].Attempt {
			t.Errorf("attempt %d = %d", i, row.Attempts)
		}
		if delta != g.Backoff[i].DeltaDays {
			t.Errorf("delta %d = %v days; golden %v",
				i, delta, g.Backoff[i].DeltaDays)
		}
		if pstr(row.FirstFailedAt) != pstr(row.LastFailedAt) {
			t.Errorf("first != last on first failure: %q vs %q",
				pstr(row.FirstFailedAt), pstr(row.LastFailedAt))
		}
		if pstr(row.LastError) != g.Backoff[i].ErrorField {
			t.Errorf("error field = %q; golden %q",
				pstr(row.LastError), g.Backoff[i].ErrorField)
		}
	}
	// The refresh: attempts 2, first_failed_at survives.
	if err := bdb.EnqueueRetry("https://backoff0.example/",
		"second failure"); err != nil {
		t.Fatal(err)
	}
	row, err := bdb.RetryRow("https://backoff0.example/")
	if err != nil || row == nil {
		t.Fatalf("retry_row = %v, err = %v", row, err)
	}
	if row.Attempts != 2 {
		t.Fatalf("refresh attempts = %d; want 2", row.Attempts)
	}
	if row.Attempts != pyInt(g.BackoffRefresh["attempts"]) {
		t.Fatalf("refresh attempts vs golden: %d != %v",
			row.Attempts, g.BackoffRefresh["attempts"])
	}

	// The truncation battery — Python slices by CODEPOINT.
	longErr := strings.Repeat("é", 260) + strings.Repeat("x", 300)
	longReason := strings.Repeat("🗑", 120) + strings.Repeat("y", 150)
	tdb := newTestDB(t)
	if err := tdb.EnqueueRetry("https://trunc.example/", longErr); err != nil {
		t.Fatal(err)
	}
	if err := tdb.Dismiss("https://trunc.example/", longReason); err != nil {
		t.Fatal(err)
	}
	erow, err := tdb.RetryRow("https://trunc.example/")
	if err != nil || erow == nil {
		t.Fatalf("retry_row = %v, err = %v", erow, err)
	}
	drow, err := tdb.DismissedRow("https://trunc.example/")
	if err != nil || drow == nil {
		t.Fatalf("dismissed_row = %v, err = %v", drow, err)
	}
	truncErr := helpers.CutRunes(longErr, 500)
	truncReason := helpers.CutRunes(longReason, 200)
	truncErrRunes := []rune(truncErr)
	truncReasonRunes := []rune(truncReason)
	if got := int64(len([]rune(truncErr))); got != pyInt(g.Truncation["error_runes"]) {
		t.Errorf("error runes = %d; golden %v", got, g.Truncation["error_runes"])
	}
	if got := int64(len(truncErr)); got != pyInt(g.Truncation["error_bytes"]) {
		t.Errorf("error bytes = %d; golden %v", got, g.Truncation["error_bytes"])
	}
	if string(truncErrRunes[:3]) != pyStr(t, g.Truncation["error_head"]) {
		t.Errorf("error head = %q", string(truncErrRunes[:3]))
	}
	if string(truncErrRunes[len(truncErrRunes)-3:]) != pyStr(t, g.Truncation["error_tail"]) {
		t.Errorf("error tail = %q", string(truncErrRunes[len(truncErrRunes)-3:]))
	}
	if got := int64(len([]rune(truncReason))); got != pyInt(g.Truncation["reason_runes"]) {
		t.Errorf("reason runes = %d; golden %v", got, g.Truncation["reason_runes"])
	}
	if got := int64(len(truncReason)); got != pyInt(g.Truncation["reason_bytes"]) {
		t.Errorf("reason bytes = %d; golden %v", got, g.Truncation["reason_bytes"])
	}
	if string(truncReasonRunes[:2]) != pyStr(t, g.Truncation["reason_head"]) {
		t.Errorf("reason head = %q", string(truncReasonRunes[:2]))
	}
	// and the DB round-trip carries the truncated bytes
	if pstr(erow.LastError) != truncErr {
		t.Errorf("stored last_error is not the rune-truncated value")
	}
	if pstr(drow.Reason) != truncReason {
		t.Errorf("stored reason is not the rune-truncated value")
	}
}

// ---------------------------------------------------------------------------
// The schema golden — the adopt-as-is DDL (ADR-0003; the CAST-law guard).
// ---------------------------------------------------------------------------

type schemaGolden struct {
	Schema       int                `json:"schema"`
	Objects      [][]any            `json:"objects"`
	TableColumns map[string][][]any `json:"table_columns"`
}

func TestSchemaIdentity(t *testing.T) {
	var g schemaGolden
	decodeGolden(t, "websitestate_schema.golden.json", &g)
	db := newTestDB(t)

	rows, err := db.SQL().Query(
		"SELECT type, name, tbl_name, sql FROM sqlite_master " +
			"ORDER BY type, name")
	if err != nil {
		t.Fatal(err)
	}
	defer rows.Close()
	var objects [][]any
	for rows.Next() {
		var typ, name, tbl string
		var sqlText sql.NullString
		if err := rows.Scan(&typ, &name, &tbl, &sqlText); err != nil {
			t.Fatal(err)
		}
		var v any // NULL stays nil (the autoindex rows carry no DDL)
		if sqlText.Valid {
			v = sqlText.String
		}
		objects = append(objects, []any{typ, name, tbl, v})
	}
	if err := rows.Err(); err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(normalizeRows(objects), normalizeRows(g.Objects)) {
		t.Errorf("sqlite_master != golden:\n got: %#v\nwant: %#v",
			normalizeRows(objects), normalizeRows(g.Objects))
	}

	for table, want := range g.TableColumns {
		info, err := db.SQL().Query("PRAGMA table_info(" + table + ")")
		if err != nil {
			t.Fatal(err)
		}
		var cols [][]any
		for info.Next() {
			// PRAGMA table_info: cid, name, type, notnull, dflt_value, pk
			var cid int64
			var name, typ string
			var notnull int64
			var dflt any
			var pk int64
			if err := info.Scan(&cid, &name, &typ, &notnull, &dflt, &pk); err != nil {
				t.Fatal(err)
			}
			cols = append(cols, []any{name, typ, notnull, dflt, pk})
		}
		info.Close()
		if !reflect.DeepEqual(normalizeRows(cols), normalizeRows(want)) {
			t.Errorf("%s table_info != golden:\n got: %#v\nwant: %#v",
				table, normalizeRows(cols), normalizeRows(want))
		}
	}
}

// ---------------------------------------------------------------------------
// THE T-23 ACCEPTANCE — open the real Python-created fixture, every
// table byte-exact vs the golden, Go writes survive close+reopen.
// ---------------------------------------------------------------------------

type goldenTable struct {
	Columns []string `json:"columns"`
	Rows    [][]any  `json:"rows"`
}

type fixtureGolden struct {
	Schema            int    `json:"schema"`
	FixtureSha256     string `json:"fixture_sha256"`
	NoSidecars        bool   `json:"no_sidecars_after_close"`
	PragmasThroughRef struct {
		JournalMode string `json:"journal_mode"`
		BusyTimeout int64  `json:"busy_timeout"`
		Synchronous int64  `json:"synchronous"`
	} `json:"pragmas_through_reference"`
	Tables  map[string]goldenTable `json:"tables"`
	Getters struct {
		IsProcessed   map[string]bool           `json:"is_processed"`
		ProcessedRow  map[string]map[string]any `json:"processed_row"`
		RetryRow      map[string]map[string]any `json:"retry_row"`
		AllRetryCount int64                     `json:"all_retry_rows_count"`
		AllRetryURLs  []string                  `json:"all_retry_rows_urls"`
		IsDismissed   map[string]bool           `json:"is_dismissed"`
		DismissedRow  map[string]any            `json:"dismissed_row"`
		DismissedAll  []map[string]any          `json:"dismissed_rows_all"`
		DismissedAuto []map[string]any          `json:"dismissed_rows_auto_prefix"`
		IsSettled     bool                      `json:"is_settled"`
		SettledCount  int64                     `json:"settled_count"`
		DueFixedNow   []string                  `json:"due_retries_fixed_now"`
		Meta          struct {
			Get    string  `json:"get"`
			Absent *string `json:"absent"`
		} `json:"meta"`
		UndismissProbes    []bool          `json:"undismiss_probes"`
		ForgetFailedProbes []bool          `json:"forget_failed_probes"`
		ForgetRowProbe     bool            `json:"forget_row_probe"`
		ResetProbe         bool            `json:"reset_probe"`
		BurnedAfterReset   int64           `json:"burned_after_reset_attempts"`
		RearmCount         int64           `json:"rearm_count"`
		PurgeReport        purgeReportJSON `json:"purge_report"`
		PurgeAgain         purgeReportJSON `json:"purge_again"`
	} `json:"getters"`
}

type purgeReportJSON struct {
	Retries      int64      `json:"retries"`
	Placeholders [][]string `json:"placeholders"`
	Dismissed    int64      `json:"dismissed"`
}

func dumpTable(t *testing.T, db *WebsiteStateDB, table,
	orderBy string) ([]string, [][]any) {
	t.Helper()
	return dumpColumns(t, db, "SELECT * FROM "+table+
		" ORDER BY "+orderBy)
}

// dumpColumns runs an explicit SELECT and scans every row raw (the
// golden comparison shape).
func dumpColumns(t *testing.T, db *WebsiteStateDB, query string) (
	[]string, [][]any) {
	t.Helper()
	rows, err := db.SQL().Query(query)
	if err != nil {
		t.Fatalf("select: %s: %v", query, err)
	}
	defer rows.Close()
	cols, err := rows.Columns()
	if err != nil {
		t.Fatalf("columns: %v", err)
	}
	var out [][]any
	for rows.Next() {
		vals := make([]any, len(cols))
		ptrs := make([]any, len(cols))
		for i := range vals {
			ptrs[i] = &vals[i]
		}
		if err := rows.Scan(ptrs...); err != nil {
			t.Fatalf("scan: %v", err)
		}
		out = append(out, vals)
	}
	if err := rows.Err(); err != nil {
		t.Fatalf("rows: %v", err)
	}
	return cols, out
}

func TestOpenPythonCreatedFixture(t *testing.T) {
	var g fixtureGolden
	decodeGolden(t, "websitestate_fixture_content.golden.json", &g)
	src := filepath.Join("testdata", "websitestate_python_created.db")

	// The atomic-pair tie: the committed fixture is exactly the file the
	// content golden describes.
	data, err := os.ReadFile(src)
	if err != nil {
		t.Fatal(err)
	}
	if got := sha256Hex(data); got != g.FixtureSha256 {
		t.Fatalf("fixture sha256 = %s; golden records %s "+
			"(regenerate BOTH with testdiff/goldens/dump_websitestate.py)",
			got, g.FixtureSha256)
	}
	if !g.NoSidecars {
		t.Fatal("golden records sidecars after close — broken fixture")
	}

	// Never mutate testdata: work on a copy.
	work := filepath.Join(t.TempDir(), "websitestate_python_created.db")
	if err := os.WriteFile(work, data, 0o644); err != nil {
		t.Fatal(err)
	}

	db, err := NewWebsiteStateDB(work)
	if err != nil {
		t.Fatalf("open Python-created fixture: %v", err)
	}
	defer db.Close()

	// The pragmas: the Go open sets busy_timeout=30000 like the
	// reference, and — the DOCUMENTED unified-pragmas divergence
	// (store/doc.go) — flips a lone WebsiteStateDB file from the
	// reference's 'delete'/FULL to wal/NORMAL.
	var mode string
	var busy, sync int64
	if err := db.SQL().QueryRow("PRAGMA journal_mode").Scan(&mode); err != nil {
		t.Fatal(err)
	}
	if err := db.SQL().QueryRow("PRAGMA busy_timeout").Scan(&busy); err != nil {
		t.Fatal(err)
	}
	if err := db.SQL().QueryRow("PRAGMA synchronous").Scan(&sync); err != nil {
		t.Fatal(err)
	}
	if busy != g.PragmasThroughRef.BusyTimeout {
		t.Fatalf("busy_timeout = %d; reference sets %d", busy,
			g.PragmasThroughRef.BusyTimeout)
	}
	if mode != "wal" || sync != 1 {
		t.Fatalf("Go pragmas = %s/%d; the unified law is wal/1", mode, sync)
	}
	if g.PragmasThroughRef.JournalMode != "delete" ||
		g.PragmasThroughRef.Synchronous != 2 {
		t.Fatalf("golden records unexpected reference pragmas: %s/%d",
			g.PragmasThroughRef.JournalMode, g.PragmasThroughRef.Synchronous)
	}

	// Every table byte-exact vs the golden.
	for table, want := range g.Tables {
		cols, rows := dumpTable(t, db, table, tablePK[table])
		if !reflect.DeepEqual(cols, want.Columns) {
			t.Errorf("%s columns = %v; golden %v", table, cols, want.Columns)
		}
		if !reflect.DeepEqual(normalizeRows(rows), normalizeRows(want.Rows)) {
			t.Errorf("%s rows != golden:\n got: %#v\nwant: %#v",
				table, normalizeRows(rows), normalizeRows(want.Rows))
		}
	}

	// The getter battery, read back through the port's own getters.
	for u, want := range g.Getters.IsProcessed {
		if got, err := db.IsProcessed(u); err != nil || got != want {
			t.Errorf("is_processed(%s) = %v/%v; golden %v", u, got, err, want)
		}
	}
	for u, want := range g.Getters.ProcessedRow {
		got, err := db.ProcessedRow(u)
		if err != nil {
			t.Errorf("processed_row(%s): %v", u, err)
			continue
		}
		assertRowDict(t, "processed_row("+u+")", rowToDict(got), want)
	}
	for u, want := range g.Getters.RetryRow {
		got, err := db.RetryRow(u)
		if err != nil {
			t.Errorf("retry_row(%s): %v", u, err)
			continue
		}
		assertRowDict(t, "retry_row("+u+")", retryToDict(got), want)
	}
	if rows, err := db.AllRetryRows(); err != nil ||
		int64(len(rows)) != g.Getters.AllRetryCount {
		t.Errorf("all_retry_rows count = %d/%v; golden %d",
			len(rows), err, g.Getters.AllRetryCount)
	} else {
		var urls []string
		for _, r := range rows {
			urls = append(urls, r.URL)
		}
		if !reflect.DeepEqual(urls, g.Getters.AllRetryURLs) {
			t.Errorf("all_retry_rows urls = %v; golden %v",
				urls, g.Getters.AllRetryURLs)
		}
	}
	for u, want := range g.Getters.IsDismissed {
		if got, err := db.IsDismissed(u); err != nil || got != want {
			t.Errorf("is_dismissed(%s) = %v/%v; golden %v", u, got, err, want)
		}
	}
	if got, err := db.DismissedRow("https://banished.example/"); err != nil {
		t.Errorf("dismissed_row: %v", err)
	} else {
		assertRowDict(t, "dismissed_row", dismissedToDict(got),
			g.Getters.DismissedRow)
	}
	all, err := db.DismissedRows("")
	if err != nil {
		t.Fatal(err)
	}
	if len(all) != len(g.Getters.DismissedAll) {
		t.Fatalf("dismissed_rows() len = %d; golden %d",
			len(all), len(g.Getters.DismissedAll))
	}
	for i, want := range g.Getters.DismissedAll {
		assertRowDict(t, fmt.Sprintf("dismissed_rows()[%d]", i),
			dismissedToDict(&all[i]), want)
	}
	auto, err := db.DismissedRows("auto-verdict:")
	if err != nil {
		t.Fatal(err)
	}
	if len(auto) != len(g.Getters.DismissedAuto) {
		t.Fatalf("dismissed_rows(auto-verdict:) len = %d; golden %d",
			len(auto), len(g.Getters.DismissedAuto))
	}
	for i, want := range g.Getters.DismissedAuto {
		assertRowDict(t, fmt.Sprintf("dismissed_rows(auto)[%d]", i),
			dismissedToDict(&auto[i]), want)
	}
	if got, err := db.IsSettled(noSlash); err != nil || got != g.Getters.IsSettled {
		t.Errorf("is_settled = %v/%v; golden %v", got, err, g.Getters.IsSettled)
	}
	if got, err := db.SettledCount(); err != nil ||
		int64(got) != g.Getters.SettledCount {
		t.Errorf("settled_count = %d/%v; golden %d", got, err,
			g.Getters.SettledCount)
	}
	// due_retries at the golden's FIXED now (2027-06-01T12:00:00 local).
	fixedNow := time.Date(2027, 6, 1, 12, 0, 0, 0, time.Local)
	if got, err := db.DueRetriesAt(fixedNow); err != nil {
		t.Errorf("due_retries(fixed now): %v", err)
	} else if !reflect.DeepEqual(got, g.Getters.DueFixedNow) {
		t.Errorf("due_retries(fixed now) = %v; golden %v",
			got, g.Getters.DueFixedNow)
	}
	if v, err := db.GetMeta("proxy_epoch"); err != nil ||
		pstr(v) != g.Getters.Meta.Get {
		t.Errorf("get_meta(proxy_epoch) = %v/%v; golden %q",
			v, err, g.Getters.Meta.Get)
	}
	if v, err := db.GetMeta("never-set"); err != nil || v != nil {
		t.Errorf("get_meta(never-set) = %v/%v; golden null", v, err)
	}

	// THE READ/WRITE PROBE (the acceptance): a Go write survives
	// close+reopen next to the Python rows, in the same shapes.
	if err := db.MarkProcessed("https://go-write.example/",
		"/vault/Go/Write/g.md", "Go", "Write", "full"); err != nil {
		t.Fatal(err)
	}
	if err := db.EnqueueRetry("https://go-write.example/", "go failure"); err != nil {
		t.Fatal(err)
	}
	if err := db.Dismiss("https://go-dismiss.example/",
		"go dismissed"); err != nil {
		t.Fatal(err)
	}
	if err := db.Close(); err != nil {
		t.Fatal(err)
	}
	db2, err := NewWebsiteStateDB(work)
	if err != nil {
		t.Fatalf("reopen: %v", err)
	}
	defer db2.Close()
	row, err := db2.ProcessedRow("https://go-write.example/")
	if err != nil || row == nil {
		t.Fatalf("go row after reopen = %v, err = %v", row, err)
	}
	if pstr(row.ProcessedAt) != store.PyISOFormatSeconds(
		mustParsePyISO(t, pstr(row.ProcessedAt))) {
		t.Fatalf("Go-written processed_at is not the naive seconds shape: %q",
			pstr(row.ProcessedAt))
	}
	rrow, err := db2.RetryRow("https://go-write.example/")
	if err != nil || rrow == nil || rrow.Attempts != 1 {
		t.Fatalf("go retry row after reopen = %+v, err = %v", rrow, err)
	}
	if ok, err := db2.IsDismissed("https://go-dismiss.example/"); err != nil || !ok {
		t.Fatalf("go dismissal after reopen = %v, err = %v", ok, err)
	}
	// and the Python rows are untouched
	prow, err := db2.ProcessedRow(noSlash)
	if err != nil || prow == nil || pstr(prow.NotePath) !=
		"/vault/Design/Assets/cleanup.md" {
		t.Fatalf("python row after go writes = %+v, err = %v", prow, err)
	}
}

// tablePK — the ORDER BY key per table (mirrors the generator's
// TABLE_ORDER).
var tablePK = map[string]string{
	"websites_processed":  "url",
	"website_retry_queue": "url",
	"dismissed_urls":      "url",
	"website_state_meta":  "key",
	"websites_settled":    "url",
}

// ---------------------------------------------------------------------------
// The behavior golden — re-run every probe in Go and compare against the
// reference's own answers.
// ---------------------------------------------------------------------------

type behaviorGolden struct {
	Schema int `json:"schema"`
	Probes struct {
		Healing struct {
			FirstReport   map[string]int64 `json:"first_report"`
			SecondReport  map[string]int64 `json:"second_report"`
			ProcessedRows [][]any          `json:"processed_rows"`
			RetryRows     [][]any          `json:"retry_rows"`
			SettledRows   [][]any          `json:"settled_rows"`
			DismissedRows [][]any          `json:"dismissed_rows"`
		} `json:"healing"`
		HealingNoop          map[string]int64 `json:"healing_noop"`
		HealingCanonicalOnly map[string]int64 `json:"healing_canonical_only"`
		SettleExisting       struct {
			First          map[string]any `json:"first"`
			SecondAfterNew map[string]any `json:"second_after_new_rows"`
			ThirdWithEx    map[string]any `json:"third_with_extras"`
			NewRowSettled  bool           `json:"new_row_settled"`
			QueueAfter     []string       `json:"queue_after"`
			DueAfter       []string       `json:"due_after"`
			MetaStamped    bool           `json:"meta_stamped"`
			SettledCount   int64          `json:"settled_count"`
		} `json:"settle_existing"`
		SettleQueueHistory struct {
			First        map[string]any `json:"first"`
			SettledCount int64          `json:"settled_one_spelling_count"`
			Second       map[string]any `json:"second"`
			LaterSettled bool           `json:"later_settled"`
			Third        map[string]any `json:"third_after_refailure"`
			QueueAfter   []string       `json:"queue_after"`
			MetaStamped  bool           `json:"meta_stamped"`
		} `json:"settle_queue_history"`
		SettleQueueHistoryCountHonesty struct {
			Report       map[string]any `json:"report"`
			IsSettled    bool           `json:"is_settled"`
			SettledCount int64          `json:"settled_count"`
		} `json:"settle_queue_history_count_honesty"`
		SettleQueueHistoryEmpty struct {
			Report       map[string]any `json:"report"`
			SettledCount int64          `json:"settled_count"`
		} `json:"settle_queue_history_empty"`
		DueRetriesFixedNow   []string `json:"due_retries_fixed_now"`
		DueRetriesDefaultNow []string `json:"due_retries_default_now"`
	} `json:"probes"`
}

func TestBehaviorGolden(t *testing.T) {
	var g behaviorGolden
	decodeGolden(t, "websitestate_behavior.golden.json", &g)

	// -- the healing matrix --
	db := newTestDB(t)
	alive := filepath.Join(t.TempDir(), "Cleanup Pictures.md")
	if err := os.WriteFile(alive, []byte("note"), 0o644); err != nil {
		t.Fatal(err)
	}
	rawInsert(t, db, "websites_processed",
		[]string{"url", "note_path", "category", "subcategory",
			"fetch_status", "processed_at"},
		withSlash, alive, "Design", "Assets", "full", "2026-10-01")
	rawInsert(t, db, "websites_processed",
		[]string{"url", "note_path", "category", "subcategory",
			"fetch_status", "processed_at"},
		noSlash, "gone.md", "", "", "failed", "2026-10-02")
	rawInsert(t, db, "website_retry_queue",
		[]string{"url", "attempts", "last_error", "next_attempt_at",
			"first_failed_at", "last_failed_at"},
		noSlash, 1, "e", "2026-10-01", "2026-10-01", "2026-10-01")
	rawInsert(t, db, "website_retry_queue",
		[]string{"url", "attempts", "last_error", "next_attempt_at",
			"first_failed_at", "last_failed_at"},
		withSlash, 3, "e", "2026-10-03", "2026-10-01", "2026-10-03")
	rawInsert(t, db, "websites_settled",
		[]string{"url", "settled_at"}, withSlash, "2026-10-05")
	rawInsert(t, db, "websites_settled",
		[]string{"url", "settled_at"}, noSlash, "2026-10-06")
	rawInsert(t, db, "dismissed_urls",
		[]string{"url", "reason", "dismissed_at"},
		withSlash, "r1", "2026-10-05")
	rawInsert(t, db, "dismissed_urls",
		[]string{"url", "reason", "dismissed_at"},
		noSlash, "r2", "2026-10-06")
	rep1, err := db.NormalizeLedgerKeys()
	if err != nil {
		t.Fatal(err)
	}
	_, procRows := dumpTable(t, db, "websites_processed", "url")
	_, retryRows := dumpColumns(t, db,
		"SELECT url, attempts FROM website_retry_queue ORDER BY url")
	_, settledRows := dumpTable(t, db, "websites_settled", "url")
	_, dismissedRows := dumpTable(t, db, "dismissed_urls", "url")
	rep2, err := db.NormalizeLedgerKeys()
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(reportMap(rep1, 0, 0), normIntMap(g.Probes.Healing.FirstReport)) {
		t.Errorf("healing first report = %v; golden %v",
			reportMap(rep1, 0, 0), g.Probes.Healing.FirstReport)
	}
	if !reflect.DeepEqual(reportMap(rep2, 0, 0), normIntMap(g.Probes.Healing.SecondReport)) {
		t.Errorf("healing second report = %v; golden %v",
			reportMap(rep2, 0, 0), g.Probes.Healing.SecondReport)
	}
	// processed rows: [url, basename] (the golden records basenames —
	// the alive-note path is per-run)
	var gotProc [][]any
	for _, r := range procRows {
		gotProc = append(gotProc, []any{r[0],
			filepath.Base(fmt.Sprint(r[1]))})
	}
	if !reflect.DeepEqual(normalizeRows(gotProc),
		normalizeRows(g.Probes.Healing.ProcessedRows)) {
		t.Errorf("healed processed rows = %#v; golden %#v",
			normalizeRows(gotProc), g.Probes.Healing.ProcessedRows)
	}
	if !reflect.DeepEqual(normalizeRows(retryRows),
		normalizeRows(g.Probes.Healing.RetryRows)) {
		t.Errorf("healed retry rows = %#v; golden %#v",
			normalizeRows(retryRows), g.Probes.Healing.RetryRows)
	}
	if !reflect.DeepEqual(normalizeRows(settledRows),
		normalizeRows(g.Probes.Healing.SettledRows)) {
		t.Errorf("healed settled rows = %#v; golden %#v",
			normalizeRows(settledRows), g.Probes.Healing.SettledRows)
	}
	if !reflect.DeepEqual(normalizeRows(dismissedRows),
		normalizeRows(g.Probes.Healing.DismissedRows)) {
		t.Errorf("healed dismissed rows = %#v; golden %#v",
			normalizeRows(dismissedRows), g.Probes.Healing.DismissedRows)
	}

	// -- the quiet noop + the already-canonical pass --
	db = newTestDB(t)
	rep, err := db.NormalizeLedgerKeys()
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(reportMap(rep, 0, 0), normIntMap(g.Probes.HealingNoop)) {
		t.Errorf("healing noop = %v; golden %v", reportMap(rep, 0, 0),
			g.Probes.HealingNoop)
	}
	if err := db.MarkProcessed("https://plain.example/", "n.md",
		"A", "B", "full"); err != nil {
		t.Fatal(err)
	}
	if rep, err = db.NormalizeLedgerKeys(); err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(reportMap(rep, 0, 0), normIntMap(g.Probes.HealingCanonicalOnly)) {
		t.Errorf("healing canonical-only = %v; golden %v",
			reportMap(rep, 0, 0), g.Probes.HealingCanonicalOnly)
	}

	// -- settle_existing --
	db = newTestDB(t)
	if err := db.MarkProcessed("https://a.example/", "n.md",
		"Design", "Assets", "full"); err != nil {
		t.Fatal(err)
	}
	if err := db.EnqueueRetry("https://b.example/", "err"); err != nil {
		t.Fatal(err)
	}
	if err := db.EnqueueRetry("https://b.example/", "err"); err != nil {
		t.Fatal(err)
	}
	if err := db.Dismiss("https://c.example/",
		"note deleted by owner"); err != nil {
		t.Fatal(err)
	}
	se1, err := db.SettleExisting(nil)
	if err != nil {
		t.Fatal(err)
	}
	if err := db.MarkProcessed("https://new.example/", "n2.md",
		"", "", "failed"); err != nil {
		t.Fatal(err)
	}
	if err := db.EnqueueRetry("https://new.example/", "err"); err != nil {
		t.Fatal(err)
	}
	se2, err := db.SettleExisting(nil)
	if err != nil {
		t.Fatal(err)
	}
	se3, err := db.SettleExisting([]string{
		"https://hand.example/", "https://hand.example/", "", ""})
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(settleExistingMap(se1), normAnyMap(g.Probes.SettleExisting.First)) {
		t.Errorf("settle_existing first = %v; golden %v",
			settleExistingMap(se1), g.Probes.SettleExisting.First)
	}
	if !reflect.DeepEqual(settleExistingMap(se2), normAnyMap(g.Probes.SettleExisting.SecondAfterNew)) {
		t.Errorf("settle_existing second = %v; golden %v",
			settleExistingMap(se2), g.Probes.SettleExisting.SecondAfterNew)
	}
	if !reflect.DeepEqual(settleExistingMap(se3), normAnyMap(g.Probes.SettleExisting.ThirdWithEx)) {
		t.Errorf("settle_existing third = %v; golden %v",
			settleExistingMap(se3), g.Probes.SettleExisting.ThirdWithEx)
	}
	if ok, err := db.IsSettled("https://new.example/"); err != nil ||
		ok != g.Probes.SettleExisting.NewRowSettled {
		t.Errorf("new row settled = %v; golden %v", ok,
			g.Probes.SettleExisting.NewRowSettled)
	}
	if rows, err := db.AllRetryRows(); err != nil {
		t.Fatal(err)
	} else {
		var urls []string
		for _, r := range rows {
			urls = append(urls, r.URL)
		}
		if !reflect.DeepEqual(urls, g.Probes.SettleExisting.QueueAfter) {
			t.Errorf("queue after = %v; golden %v",
				urls, g.Probes.SettleExisting.QueueAfter)
		}
	}
	fixedNow := time.Date(2027, 6, 1, 12, 0, 0, 0, time.Local)
	if due, err := db.DueRetriesAt(fixedNow); err != nil {
		t.Fatal(err)
	} else if !reflect.DeepEqual(due, g.Probes.SettleExisting.DueAfter) {
		t.Errorf("due after = %v; golden %v",
			due, g.Probes.SettleExisting.DueAfter)
	}
	if v, err := db.GetMeta(SettledMetaKey); err != nil ||
		(v != nil) != g.Probes.SettleExisting.MetaStamped {
		t.Errorf("meta stamped = %v; golden %v", v != nil,
			g.Probes.SettleExisting.MetaStamped)
	}
	if n, err := db.SettledCount(); err != nil ||
		int64(n) != g.Probes.SettleExisting.SettledCount {
		t.Errorf("settled count = %d; golden %d", n,
			g.Probes.SettleExisting.SettledCount)
	}

	// -- settle_queue_history --
	db = newTestDB(t)
	if err := db.EnqueueRetry("https://fresh-failure.example/",
		"err"); err != nil {
		t.Fatal(err)
	}
	qh1, err := db.SettleQueueHistory([]string{
		"https://qh.example/", "https://cleanup.pictures/",
		"https://cleanup.pictures"})
	if err != nil {
		t.Fatal(err)
	}
	qh2, err := db.SettleQueueHistory([]string{"https://later.example/"})
	if err != nil {
		t.Fatal(err)
	}
	if err := db.EnqueueRetry("https://qh.example/",
		"mid-flight failure"); err != nil {
		t.Fatal(err)
	}
	qh3, err := db.SettleQueueHistory([]string{"https://qh.example/"})
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(settleQueueMap(qh1), normAnyMap(g.Probes.SettleQueueHistory.First)) {
		t.Errorf("settle_queue_history first = %v; golden %v",
			settleQueueMap(qh1), g.Probes.SettleQueueHistory.First)
	}
	if n, err := db.SettledCount(); err != nil ||
		int64(n) != g.Probes.SettleQueueHistory.SettledCount {
		t.Errorf("settled count = %d; golden %d", n,
			g.Probes.SettleQueueHistory.SettledCount)
	}
	if !reflect.DeepEqual(settleQueueMap(qh2), normAnyMap(g.Probes.SettleQueueHistory.Second)) {
		t.Errorf("settle_queue_history second = %v; golden %v",
			settleQueueMap(qh2), g.Probes.SettleQueueHistory.Second)
	}
	if ok, err := db.IsSettled("https://later.example/"); err != nil ||
		ok != g.Probes.SettleQueueHistory.LaterSettled {
		t.Errorf("later settled = %v; golden %v", ok,
			g.Probes.SettleQueueHistory.LaterSettled)
	}
	if !reflect.DeepEqual(settleQueueMap(qh3), normAnyMap(g.Probes.SettleQueueHistory.Third)) {
		t.Errorf("settle_queue_history third = %v; golden %v",
			settleQueueMap(qh3), g.Probes.SettleQueueHistory.Third)
	}
	if rows, err := db.AllRetryRows(); err != nil {
		t.Fatal(err)
	} else {
		var urls []string
		for _, r := range rows {
			urls = append(urls, r.URL)
		}
		if !reflect.DeepEqual(urls, g.Probes.SettleQueueHistory.QueueAfter) {
			t.Errorf("queue after = %v; golden %v",
				urls, g.Probes.SettleQueueHistory.QueueAfter)
		}
	}
	if v, err := db.GetMeta(QueueHistorySettledMetaKey); err != nil ||
		(v != nil) != g.Probes.SettleQueueHistory.MetaStamped {
		t.Errorf("meta stamped = %v; golden %v", v != nil,
			g.Probes.SettleQueueHistory.MetaStamped)
	}

	// -- count honesty + empty inputs --
	db = newTestDB(t)
	if _, err := db.SettleExisting(
		[]string{"https://pre.example/"}); err != nil {
		t.Fatal(err)
	}
	qh, err := db.SettleQueueHistory([]string{"https://pre.example/"})
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(settleQueueMap(qh), normAnyMap(g.Probes.SettleQueueHistoryCountHonesty.Report)) {
		t.Errorf("count honesty report = %v; golden %v",
			settleQueueMap(qh), g.Probes.SettleQueueHistoryCountHonesty.Report)
	}
	if ok, err := db.IsSettled("https://pre.example/"); err != nil ||
		ok != g.Probes.SettleQueueHistoryCountHonesty.IsSettled {
		t.Errorf("is_settled = %v; golden %v", ok,
			g.Probes.SettleQueueHistoryCountHonesty.IsSettled)
	}
	if n, err := db.SettledCount(); err != nil ||
		int64(n) != g.Probes.SettleQueueHistoryCountHonesty.SettledCount {
		t.Errorf("settled count = %d; golden %d", n,
			g.Probes.SettleQueueHistoryCountHonesty.SettledCount)
	}

	db = newTestDB(t)
	qh, err = db.SettleQueueHistory([]string{"", ""})
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(settleQueueMap(qh), normAnyMap(g.Probes.SettleQueueHistoryEmpty.Report)) {
		t.Errorf("empty report = %v; golden %v",
			settleQueueMap(qh), g.Probes.SettleQueueHistoryEmpty.Report)
	}
	if n, err := db.SettledCount(); err != nil ||
		int64(n) != g.Probes.SettleQueueHistoryEmpty.SettledCount {
		t.Errorf("empty settled count = %d; golden %d", n,
			g.Probes.SettleQueueHistoryEmpty.SettledCount)
	}

	// -- the due_retries battery at the FIXED now --
	db = newTestDB(t)
	for i := 0; i < 3; i++ {
		if err := db.EnqueueRetry("https://cap1.example/", "e"); err != nil {
			t.Fatal(err)
		}
	}
	for _, tc := range []struct{ url, next string }{
		{"https://due.example", "2027-01-01T00:00:00"},
		{"https://future.example", "2027-06-15T00:00:00"},
		{"https://boundary.example", "2027-06-01T12:00:00"},
		{"https://garbage.example", "not-a-date"},
		{"https://dateonly.example", "2027-05-30"},
		{"https://aware.example", "2027-05-30T00:00:00+00:00"},
	} {
		if err := db.EnqueueRetry(tc.url+"/", "e"); err != nil {
			t.Fatal(err)
		}
		db.Lock()
		_, err := db.SQL().Exec(
			"UPDATE website_retry_queue SET next_attempt_at=? WHERE url=?",
			tc.next, tc.url)
		db.Unlock()
		if err != nil {
			t.Fatal(err)
		}
	}
	if due, err := db.DueRetriesAt(fixedNow); err != nil {
		t.Fatal(err)
	} else {
		var sorted []string = due
		// the golden is sorted; Go returns scan order — sort for compare
		sortStrings(sorted)
		if !reflect.DeepEqual(sorted, g.Probes.DueRetriesFixedNow) {
			t.Errorf("due (fixed now) = %v; golden %v",
				sorted, g.Probes.DueRetriesFixedNow)
		}
	}

	// -- the default-now battery (rot-proof rows only) --
	db = newTestDB(t)
	for i := 0; i < 3; i++ {
		if err := db.EnqueueRetry("https://capped.example/", "e"); err != nil {
			t.Fatal(err)
		}
	}
	for _, tc := range []struct{ url, next string }{
		{"https://farfuture.example", "2099-01-01T00:00:00"},
		{"https://alwaysoverdue.example", "2000-01-01T00:00:00"},
		{"https://broken.example", "not-a-date"},
		{"https://aware.example", "2027-05-30T00:00:00+00:00"},
	} {
		if err := db.EnqueueRetry(tc.url+"/", "e"); err != nil {
			t.Fatal(err)
		}
		db.Lock()
		_, err := db.SQL().Exec(
			"UPDATE website_retry_queue SET next_attempt_at=? WHERE url=?",
			tc.next, tc.url)
		db.Unlock()
		if err != nil {
			t.Fatal(err)
		}
	}
	if due, err := db.DueRetries(); err != nil {
		t.Fatal(err)
	} else {
		sortStrings(due)
		if !reflect.DeepEqual(due, g.Probes.DueRetriesDefaultNow) {
			t.Errorf("due (default now) = %v; golden %v",
				due, g.Probes.DueRetriesDefaultNow)
		}
	}
}

// ---------------------------------------------------------------------------
// Small test helpers.
// ---------------------------------------------------------------------------

func pstr(p *string) string {
	if p == nil {
		return "<nil>"
	}
	return *p
}

func pyInt(v any) int64 {
	switch x := v.(type) {
	case json.Number:
		i, _ := x.Int64()
		return i
	case int64:
		return x
	case int:
		return int64(x)
	case float64:
		return int64(x)
	}
	return -1
}

func pyStr(t *testing.T, v any) string {
	t.Helper()
	if s, ok := v.(string); ok {
		return s
	}
	t.Fatalf("golden value %v is not a string", v)
	return ""
}

func mustParsePyISO(t *testing.T, s string) time.Time {
	t.Helper()
	tm, err := time.ParseInLocation("2006-01-02T15:04:05", s, time.Local)
	if err != nil {
		t.Fatalf("parse %q: %v", s, err)
	}
	return tm
}

func rowToDict(r *ProcessedRow) map[string]any {
	if r == nil {
		return nil
	}
	return map[string]any{
		"url": r.URL, "note_path": r.NotePath, "category": r.Category,
		"subcategory": r.Subcategory, "fetch_status": r.FetchStatus,
		"processed_at": r.ProcessedAt,
	}
}

func retryToDict(r *RetryRow) map[string]any {
	if r == nil {
		return nil
	}
	return map[string]any{
		"url": r.URL, "attempts": r.Attempts, "last_error": r.LastError,
		"next_attempt_at": r.NextAttemptAt,
		"first_failed_at": r.FirstFailedAt, "last_failed_at": r.LastFailedAt,
	}
}

func dismissedToDict(r *DismissedRow) map[string]any {
	if r == nil {
		return nil
	}
	return map[string]any{
		"url": r.URL, "reason": r.Reason, "dismissed_at": r.DismissedAt,
	}
}

// assertRowDict compares a Go row (as a dict of *string/int64) against
// the golden's dict (nil ⇔ JSON null).
func assertRowDict(t *testing.T, what string, got, want map[string]any) {
	t.Helper()
	if len(want) != len(got) {
		t.Errorf("%s: field count = %d; golden %d", what, len(got), len(want))
	}
	for k, wv := range want {
		gv, ok := got[k]
		if !ok {
			t.Errorf("%s: missing field %s", what, k)
			continue
		}
		switch w := wv.(type) {
		case nil:
			if gv != nil {
				t.Errorf("%s.%s = %v; golden null", what, k, gv)
			}
		case string:
			if s, ok := gv.(*string); ok {
				if s == nil {
					t.Errorf("%s.%s = nil; golden %q", what, k, w)
				} else if *s != w {
					t.Errorf("%s.%s = %q; golden %q", what, k, *s, w)
				}
			} else if gs, ok := gv.(string); ok {
				if gs != w {
					t.Errorf("%s.%s = %q; golden %q", what, k, gs, w)
				}
			}
		case json.Number:
			if i, ok := gv.(int64); ok {
				if wi, err := w.Int64(); err != nil || i != wi {
					t.Errorf("%s.%s = %d; golden %v", what, k, i, w)
				}
			} else {
				t.Errorf("%s.%s = %v (%T); golden %v", what, k, gv, gv, w)
			}
		default:
			t.Errorf("%s.%s: unhandled golden type %T", what, k, w)
		}
	}
}

func reportMap(r NormalizeLedgerReport, _, _ int) map[string]int64 {
	return map[string]int64{"rekeyed": int64(r.Rekeyed), "merged": int64(r.Merged)}
}

func settleExistingMap(r SettleExistingReport) map[string]any {
	return map[string]any{
		"settled": int64(r.Settled), "retries_cleared": int64(r.RetriesCleared),
		"already": r.Already,
	}
}

func settleQueueMap(r SettleQueueHistoryReport) map[string]any {
	return map[string]any{"settled": int64(r.Settled), "already": r.Already}
}

func normIntMap(m map[string]int64) map[string]int64 { return m }

func normAnyMap(m map[string]any) map[string]any {
	out := make(map[string]any, len(m))
	for k, v := range m {
		out[k] = pyNumber(v)
	}
	return out
}

func sortStrings(s []string) {
	for i := 1; i < len(s); i++ {
		for j := i; j > 0 && s[j] < s[j-1]; j-- {
			s[j], s[j-1] = s[j-1], s[j]
		}
	}
}
